typedef RequestId = String;

sealed class ServerMessage {
  factory ServerMessage.fromJson(Map<String, Object?> json) =>
      switch (json['type']) {
        'hello.result' => HelloResponse.fromJson(json),
        'backends.list.result' => BackendsListResponse.fromJson(json),
        'backend.status.result' => BackendStatusResponse.fromJson(json),
        'models.list.result' => ModelsListResponse.fromJson(json),
        'commands.list.result' => CommandsListResponse.fromJson(json),
        'modes.list.result' => ModesListResponse.fromJson(json),
        'sessions.list.result' => SessionsListResponse.fromJson(json),
        'session.get.result' => SessionGetResponse.fromJson(json),
        'session.create.result' => SessionCreateResponse.fromJson(json),
        'session.fork.result' => SessionForkResponse.fromJson(json),
        'session.rename.result' => SessionRenameResponse.fromJson(json),
        'session.delete.result' => SessionDeleteResponse.fromJson(json),
        'session.archive.result' => SessionArchiveResponse.fromJson(json),
        'session.attach.result' => SessionAttachResponse.fromJson(json),
        'session.detach.result' => SessionDetachResponse.fromJson(json),
        'transcript.read.result' => TranscriptReadResponse.fromJson(json),
        'attachment.read.result' => AttachmentReadResponse.fromJson(json),
        'prompt.result' => PromptResponse.fromJson(json),
        'abort.result' => AbortResponse.fromJson(json),
        'interaction.answer.result' => InteractionAnswerResponse.fromJson(json),
        'queue.cancel.result' => QueueCancelResponse.fromJson(json),
        'model.set.result' => ModelSetResponse.fromJson(json),
        'thinking.set.result' => ThinkingSetResponse.fromJson(json),
        'mode.set.result' => ModeSetResponse.fromJson(json),
        'compact.result' => CompactResponse.fromJson(json),
        'backend.call.result' => BackendCallResponse.fromJson(json),
        'error' => ErrorResponse.fromJson(json),
        'event' => EventMessage.fromJson(json),
        'catalog' => CatalogMessage.fromJson(json),
        final tag => throw FormatException('Unknown ServerMessage type: $tag'),
      };

  Map<String, Object?> toJson();
}

