  factory SessionGetResponse.fromJson(Map<String, Object?> json) {
    _expectShape(
      json,
      'SessionGetResponse',
      const <String>{'type', 'requestId', 'result'},
      const <String, String>{'type': 'session.get.result'},
    );
    return SessionGetResponse(
      requestId: _as<String>(json['requestId'], 'SessionGetResponse.requestId'),
      result: SessionGetResult.fromJson(
        _as<Map<String, Object?>>(json['result'], 'SessionGetResponse.result'),
      ),
    );
  }

  final RequestId requestId;
  final SessionGetResult result;

  @override
  Map<String, Object?> toJson() => {
    'type': 'session.get.result',
    'requestId': requestId,
    'result': result.toJson(),
  };

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SessionGetResponse &&
          _equal(requestId, other.requestId) &&
          _equal(result, other.result);

  @override
  int get hashCode => Object.hashAll([_hash(requestId), _hash(result)]);

  @override
  String toString() =>
      'SessionGetResponse(requestId: $requestId, result: $result)';
}

